<script setup lang="ts">
import { computed } from 'vue'
import { NOTEBOOK_COVERS } from '../domain/notebooks'
const props = withDefaults(defineProps<{ title: string; coverId: string; count?: number; ordinal?: number; small?: boolean }>(), { small: false })
const cover = computed(() => NOTEBOOK_COVERS.find(item => item.id === props.coverId) || NOTEBOOK_COVERS[0]!)
const labels = { k12: '课堂笔记', computer: '计算机学习', civil: '备考手记', general: '我的笔记' }
const motif = computed(() => {
  const id = cover.value.id.toLowerCase()
  if (/database|sql/.test(id)) return 'database'
  if (/algorithm|network|operating|system/.test(id)) return 'network'
  if (cover.value.audience === 'computer') return 'code'
  if (/essay|shenlun/.test(id)) return 'paper'
  if (cover.value.audience === 'civil') return 'columns'
  if (cover.value.audience === 'general') return /linen|sand|clay|terracotta/.test(id) ? 'paper' : id === 'forest' ? 'leaf' : 'orbit'
  if (['square', 'leaf', 'hexagon'].includes(cover.value.pattern)) return cover.value.pattern
  return 'orbit'
})
const palette = computed(() => ({ '--cover': cover.value.color, '--cover-ink': cover.value.ink, '--art': cover.value.art }))
</script>
<template>
  <view class="book-jacket" :class="[{ 'cover-small': small }, `motif-${motif}`]" :style="palette">
    <view class="cover-spine" />
    <view class="cover-body">
      <view class="cover-topline"><text>{{ labels[cover.audience] }}</text><text v-if="ordinal">VOL. {{ String(ordinal).padStart(2, '0') }}</text></view>
      <view class="cover-title"><text>{{ title || '我的错题本' }}</text><text>错题 · 订正 · 理解</text></view>
      <view class="subject-art" aria-hidden="true">
        <template v-if="motif === 'code'"><view class="code-line line-a"/><view class="code-line line-b"/><view class="code-line line-c"/><text class="code-symbol">{{ cover.symbol }}</text></template>
        <template v-else-if="motif === 'network'"><view class="network-line one"/><view class="network-line two"/><view class="network-line three"/><view v-for="node in 4" :key="node" class="network-node" :class="`node-${node}`"/><text class="network-symbol">{{ cover.symbol }}</text></template>
        <template v-else-if="motif === 'database'"><view class="database-body"/><view class="database-ring top"/><view class="database-ring middle"/><view class="database-ring bottom"/></template>
        <template v-else-if="motif === 'paper'"><view class="paper-shape back"/><view class="paper-shape front"><view/><view/><view/></view><text class="paper-symbol">{{ cover.symbol }}</text></template>
        <template v-else-if="motif === 'columns'"><view class="column-roof"/><view class="column-row"><view/><view/><view/></view><view class="column-base"/><text class="column-symbol">{{ cover.symbol }}</text></template>
        <template v-else><view class="art-ring ring-one"/><view class="art-ring ring-two"/><view class="art-line"/><text class="orbit-symbol">{{ cover.symbol }}</text></template>
      </view>
      <view class="cover-footer"><text>打铁匠</text><text v-if="count !== undefined">{{ count }} 道收录</text><text v-else>记录自己的理解</text></view>
    </view>
    <view class="book-elastic" />
  </view>
</template>
